//! Cross-checks this crate's hand-rolled JCS canonicalizer against real
//! `github.com/gowebpki/jcs`-produced bytes — the same JCS library the Go
//! reference implementation depends on (see root `go.mod`). No mature,
//! confirmed-trustworthy off-the-shelf Rust RFC 8785 crate was available
//! when this SDK was written, so this hand-rolled implementation is the
//! only thing standing between "signs the same bytes as the Go daemon" and
//! "silently produces incompatible signatures" — these fixtures are the
//! load-bearing proof.
//!
//! Ground truth was generated by a throwaway `go run` snippet
//! (`github.com/gowebpki/jcs`'s `Transform` applied directly to each input
//! literal) — not kept in this repo as a permanent build dependency, per
//! the porting task's instructions; the exact input/output byte pairs are
//! inlined below instead.

use awp::jcs::canonicalize;
use serde_json::Value;

fn check(input: &str, want_canonical: &str) {
    let v: Value = serde_json::from_str(input).unwrap_or_else(|e| panic!("parse {input:?}: {e}"));
    let got = canonicalize(&v);
    assert_eq!(got, want_canonical, "canonicalizing {input:?}");
}

#[test]
fn sorts_object_keys() {
    check(r#"{"b":1,"a":2}"#, r#"{"a":2,"b":1}"#);
}

#[test]
fn sorts_nested_object_keys_and_preserves_array_order() {
    check(
        r#"{"nested":{"z":1,"a":[3,2,1]},"top":"x"}"#,
        r#"{"nested":{"a":[3,2,1],"z":1},"top":"x"}"#,
    );
}

#[test]
fn escapes_strings_like_go_jcs() {
    check(
        "{\"s\":\"hello \\\"world\\\"\\nwith\\ttab and \\\\ backslash and unicode é中\"}",
        "{\"s\":\"hello \\\"world\\\"\\nwith\\ttab and \\\\ backslash and unicode é中\"}",
    );
}

#[test]
fn formats_numbers_like_go_jcs() {
    // github.com/gowebpki/jcs's own Transform of this exact input produces
    // this exact output — notably `1e21` becomes `1e+21` (RFC 8785
    // §3.2.2.3's ECMA-262 ToString exponential form) and `-0` collapses to
    // `0`.
    check(
        r#"{"neg":-1,"frac":1.5,"zero":0,"negzero":-0,"big":123456789,"exp":1e21}"#,
        r#"{"big":123456789,"exp":1e+21,"frac":1.5,"neg":-1,"negzero":0,"zero":0}"#,
    );
}

#[test]
fn empty_object_and_array() {
    check(
        r#"{"empty_obj":{},"empty_arr":[]}"#,
        r#"{"empty_arr":[],"empty_obj":{}}"#,
    );
}

#[test]
fn null_and_bools() {
    check(
        r#"{"nullval":null,"boolt":true,"boolf":false}"#,
        r#"{"boolf":false,"boolt":true,"nullval":null}"#,
    );
}

#[test]
fn top_level_array_order_preserved() {
    check(r#"[1,2,3,{"a":1}]"#, r#"[1,2,3,{"a":1}]"#);
}

#[test]
fn sorts_unicode_object_keys_by_utf16_code_unit() {
    check(
        r#"{"unicode_key_é":1,"a":2}"#,
        r#"{"a":2,"unicode_key_é":1}"#,
    );
}

#[test]
fn escapes_control_characters() {
    check(
        "{\"a\":\"control chars: \\u0001\\b\\f\"}",
        "{\"a\":\"control chars: \\u0001\\b\\f\"}",
    );
}

#[test]
fn deeply_nested_structure() {
    check(
        r#"{"deep":{"a":{"b":{"c":[1,2,{"d":"e"}]}}}}"#,
        r#"{"deep":{"a":{"b":{"c":[1,2,{"d":"e"}]}}}}"#,
    );
}
